//! ActionScript API knowledge for the Actions editor: toolbox tree and code hints.
//!
//! Two sources, merged per request:
//! - `assets/actionscript-api.json`, generated by `scripts/editor-api-index.py` from the declaration
//!   audit. It contains only `implemented_subset` / `partial` declarations, so the editor never
//!   offers an API the runtime is known not to have. New runtime support appears here as soon as
//!   its catalogue status changes and the index is regenerated (`progress.py --write-reports`).
//! - Project source units (`Project::sources`), scanned on every request, so a class written in
//!   Project files is offered immediately, without a build step.
//!
//! This is editor assistance, not a type checker: the compiler stays the only authority on what a
//! script means. Unknown receivers simply produce no hints.
pub use crate::actionscript::analysis::{Analysis, SourceClass, SourceSymbol, SymbolKind};
use crate::actionscript::analysis::{RegionKind, regions};
pub use crate::actionscript::semantic::SemanticAnalysis;
use neoflash_core::{ElementKind, Project, Script, ScriptLanguage, SourceUnit};
use serde::Deserialize;
use std::cell::RefCell;
use std::collections::{BTreeMap, HashMap, HashSet, VecDeque};
use std::sync::{Arc, OnceLock};

// Snapshots contain source declarations only. Project/instance context is supplied afresh to
// completions, so an unchanged file cannot retain stale symbols from another project file.
thread_local! {
    static ANALYSES: RefCell<VecDeque<(ScriptLanguage, Arc<Analysis>)>> = const { RefCell::new(VecDeque::new()) };
    static SEMANTICS: RefCell<VecDeque<(String, Arc<SemanticAnalysis>)>> = const { RefCell::new(VecDeque::new()) };
}

fn cached_analysis(language: ScriptLanguage, source: &str) -> Arc<Analysis> {
    ANALYSES.with(|cache| {
        let mut cache = cache.borrow_mut();
        if let Some(index) = cache
            .iter()
            .position(|(dialect, analysis)| *dialect == language && analysis.source() == source)
        {
            let entry = cache.remove(index).expect("located cache entry");
            let result = Arc::clone(&entry.1);
            cache.push_front(entry);
            return result;
        }
        let analysis = Arc::new(Analysis::new(&Script {
            language,
            source: source.into(),
        }));
        if source.len() <= 1_048_576 {
            cache.push_front((language, Arc::clone(&analysis)));
            while cache.len() > 8
                || cache.iter().map(|(_, a)| a.source().len()).sum::<usize>() > 4_194_304
            {
                cache.pop_back();
            }
        }
        analysis
    })
}

#[derive(Clone, Debug, Deserialize)]
pub struct ClassInfo {
    #[serde(default)]
    pub kind: String,
    #[serde(default)]
    pub parents: Vec<String>,
    /// `subset`, `partial`, or `members` (class itself unaudited, some members ready).
    pub status: String,
}

#[derive(Clone, Debug, Deserialize)]
pub struct Member {
    /// Qualified owner class; empty for global functions/constants and language elements.
    pub owner: String,
    pub name: String,
    /// Reference kind: method, property, constant, event, function, constructor, operator, …
    pub kind: String,
    /// Value or return type from the documented signature; may be empty.
    #[serde(rename = "type", default)]
    pub ty: String,
    #[serde(rename = "static", default)]
    pub is_static: bool,
    /// Documented parameter list for callables.
    #[serde(default)]
    pub params: Option<String>,
    /// `language` for operators, statements and directives.
    #[serde(default)]
    pub group: Option<String>,
    /// Exact active audit note, present only for a partially supported declaration.
    #[serde(default)]
    pub limitation: Option<String>,
}

impl Member {
    pub fn callable(&self) -> bool {
        self.params.is_some()
    }
    /// Text shown in hints and the toolbox: `play()`, `x`.
    pub fn label(&self) -> String {
        if self.callable() {
            format!("{}()", self.name)
        } else {
            self.name.clone()
        }
    }
    /// Text inserted for the member and the caret offset (in chars) inside it.
    pub fn insertion(&self) -> (String, usize) {
        match &self.params {
            Some(params) if !params.trim().is_empty() => {
                (format!("{}()", self.name), self.name.chars().count() + 1)
            }
            Some(_) => {
                let text = format!("{}()", self.name);
                let len = text.chars().count();
                (text, len)
            }
            None => (self.name.clone(), self.name.chars().count()),
        }
    }
}

#[derive(Debug, Default, Deserialize)]
pub struct LanguageApi {
    pub classes: BTreeMap<String, ClassInfo>,
    pub members: Vec<Member>,
    #[serde(skip)]
    by_owner: HashMap<String, Vec<usize>>,
}

#[derive(Deserialize)]
struct IndexFile {
    languages: HashMap<String, LanguageApi>,
}

struct Index {
    as2: LanguageApi,
    as3: LanguageApi,
}

fn index() -> &'static Index {
    static INDEX: OnceLock<Index> = OnceLock::new();
    INDEX.get_or_init(|| {
        let mut file: IndexFile =
            serde_json::from_str(include_str!("../assets/actionscript-api.json"))
                .expect("assets/actionscript-api.json is generated by scripts/editor-api-index.py");
        let mut take = |name: &str| {
            let mut api = file.languages.remove(name).unwrap_or_default();
            for (i, member) in api.members.iter().enumerate() {
                api.by_owner
                    .entry(member.owner.clone())
                    .or_default()
                    .push(i);
            }
            api
        };
        Index {
            as2: take("AS2"),
            as3: take("AS3"),
        }
    })
}

/// Built-in API of a script language; JavaScript/TypeScript have none (they call the host directly).
pub fn api(language: ScriptLanguage) -> Option<&'static LanguageApi> {
    match language {
        ScriptLanguage::ActionScript1 | ScriptLanguage::ActionScript2 => Some(&index().as2),
        ScriptLanguage::ActionScript3 => Some(&index().as3),
        ScriptLanguage::JavaScript | ScriptLanguage::TypeScript => None,
    }
}

fn is_as3(language: ScriptLanguage) -> bool {
    language == ScriptLanguage::ActionScript3
}

pub fn short_name(qualified: &str) -> &str {
    qualified.rsplit('.').next().unwrap_or(qualified)
}

pub fn package_of(qualified: &str) -> &str {
    qualified
        .rsplit_once('.')
        .map_or("", |(package, _)| package)
}

/// Tooltip line for a toolbox class: how far NeoFlash supports it.
pub fn class_support(api: &LanguageApi, class: &str) -> &'static str {
    match api.classes.get(class).map(|c| c.status.as_str()) {
        Some("subset") => "Implemented subset in NeoFlash",
        Some("partial") => "Partial support in NeoFlash",
        Some(_) => "Selected members supported in NeoFlash",
        None => "Project class",
    }
}

// ---------------------------------------------------------------------------------------------
// Project classes

/// A class declared in a project source unit, reduced to what hints need.
#[derive(Clone, Debug)]
pub struct ProjectClass {
    pub qualified: String,
    pub is_interface: bool,
    pub imports: Vec<String>,
    pub parent: Option<String>,
    pub members: Vec<Member>,
}

fn ident(s: &str) -> &str {
    let end = s
        .char_indices()
        .find(|(_, c)| !(c.is_alphanumeric() || *c == '_' || *c == '$' || *c == '.'))
        .map_or(s.len(), |(i, _)| i);
    &s[..end]
}

/// Declarations from the compiler lexer, including multiline signatures and only class-level members.
pub fn scan_class(unit: &SourceUnit) -> Option<ProjectClass> {
    let analysis = cached_analysis(unit.language, &unit.source);
    let class = analysis.classes().first()?;
    let mut names = HashSet::new();
    Some(ProjectClass {
        is_interface: class.is_interface,
        imports: analysis.imports(),
        qualified: class.qualified.clone(),
        parent: class.parent.clone(),
        members: analysis
            .symbols()
            .iter()
            .filter(|s| {
                s.owner.as_deref() == Some(class.qualified.as_str())
                    && !s.private
                    && s.name != short_name(&class.qualified)
            })
            .filter(|s| names.insert(s.name.clone()))
            .map(|s| Member {
                owner: class.qualified.clone(),
                name: s.name.clone(),
                kind: if s.kind == SymbolKind::Function {
                    "method"
                } else {
                    "property"
                }
                .into(),
                // Mutable class fields without an annotation have no stable signature type.
                ty: if s.kind == SymbolKind::Property
                    && !unit.source[s.range.end..]
                        .trim_start()
                        .starts_with([':', '('])
                {
                    String::new()
                } else {
                    s.ty.clone()
                },
                is_static: s.is_static,
                params: s.params.clone(),
                group: None,
                limitation: None,
            })
            .collect(),
    })
}

/// Classes of every AS2/AS3 project source unit of the given dialect family.
pub fn project_classes(project: &Project, language: ScriptLanguage) -> Vec<ProjectClass> {
    project
        .sources
        .iter()
        .filter(|unit| is_as3(unit.language) == is_as3(language))
        .filter(|unit| {
            matches!(
                unit.language,
                ScriptLanguage::ActionScript2 | ScriptLanguage::ActionScript3
            )
        })
        .filter_map(scan_class)
        .collect()
}

// ---------------------------------------------------------------------------------------------
// Code hints

/// Everything the hint resolver knows about the script being edited.
pub struct HintContext<'a> {
    pub language: ScriptLanguage,
    pub api: &'a LanguageApi,
    pub project: Vec<ProjectClass>,
    /// Class of `this` (timeline or object the script belongs to).
    pub this_class: String,
    /// Named stage instances of the current timeline and their classes.
    pub instances: Vec<(String, String)>,
}

#[derive(Clone, Debug, PartialEq)]
pub struct Hint {
    pub label: String,
    /// Right column: value/return type.
    pub detail: String,
    pub insert: String,
    /// Caret offset inside `insert`, in chars.
    pub caret: usize,
}

/// Hints at `caret` (char index): the char index where the typed prefix starts and the matches.
pub struct Hints {
    pub start: usize,
    pub items: Vec<Hint>,
}

/// Classic Flash CS4 AS1/AS2 variable name suffixes for automatic Code Hints.
pub const CLASSIC_VARIABLE_SUFFIXES: [(&str, &str); 25] = [
    ("_mc", "MovieClip"),
    ("_txt", "TextField"),
    ("_btn", "Button"),
    ("_array", "Array"),
    ("_str", "String"),
    ("_sound", "Sound"),
    ("_xml", "XML"),
    ("_xmlnode", "XMLNode"),
    ("_xmlsocket", "XMLSocket"),
    ("_so", "SharedObject"),
    ("_nc", "NetConnection"),
    ("_ns", "NetStream"),
    ("_video", "Video"),
    ("_fmt", "TextFormat"),
    ("_lv", "LoadVars"),
    ("_lc", "LocalConnection"),
    ("_color", "Color"),
    ("_date", "Date"),
    ("_err", "Error"),
    ("_cam", "Camera"),
    ("_mic", "Microphone"),
    ("_mcl", "MovieClipLoader"),
    ("_pj", "PrintJob"),
    ("_cm", "ContextMenu"),
    ("_cmi", "ContextMenuItem"),
];

impl<'a> HintContext<'a> {
    pub fn new(project: &Project, language: ScriptLanguage, this_kind: ThisKind) -> Option<Self> {
        Some(Self {
            language,
            api: api(language)?,
            project: project_classes(project, language),
            this_class: Self::kind_class(this_kind, is_as3(language)),
            instances: Vec::new(),
        })
    }

    /// `this` inside a project class file is that class.
    pub fn with_this_class(mut self, class: String) -> Self {
        self.this_class = class;
        self
    }

    pub fn with_instances(mut self, instances: Vec<(String, ThisKind)>) -> Self {
        let as3 = is_as3(self.language);
        self.instances = instances
            .into_iter()
            .map(|(name, kind)| (name, Self::kind_class(kind, as3)))
            .collect();
        self
    }

    fn kind_class(kind: ThisKind, as3: bool) -> String {
        match (kind, as3) {
            (ThisKind::MovieClip, true) => "flash.display.MovieClip",
            (ThisKind::Button, true) => "flash.display.SimpleButton",
            (ThisKind::Text, true) => "flash.text.TextField",
            (ThisKind::Bitmap, true) => "flash.display.Bitmap",
            (ThisKind::Shape, true) => "flash.display.Shape",
            (ThisKind::Button, false) => "Button",
            (ThisKind::Text, false) => "TextField",
            (_, false) => "MovieClip",
        }
        .to_owned()
    }

    fn project_class(&self, name: &str) -> Option<&ProjectClass> {
        self.project
            .iter()
            .find(|c| c.qualified == name)
            .or_else(|| {
                self.project
                    .iter()
                    .find(|c| short_name(&c.qualified) == name)
            })
    }

    /// Qualified class for a type name written in source (`MovieClip`, `flash.geom.Point`).
    pub fn resolve_class(&self, name: &str) -> Option<String> {
        if let Some(class) = self.project_class(name) {
            return Some(class.qualified.clone());
        }
        if self.api.classes.contains_key(name) {
            return Some(name.to_owned());
        }
        self.api
            .classes
            .keys()
            .find(|qualified| short_name(qualified) == name)
            .cloned()
    }

    /// Superclass chain of `class`, nearest first, including `class` itself.
    fn lineage(&self, class: &str) -> Vec<String> {
        let mut chain = vec![class.to_owned()];
        let mut seen = HashSet::new();
        let mut current = class.to_owned();
        while seen.insert(current.clone()) {
            if let Some(project) = self.project_class(&current) {
                match project
                    .parent
                    .as_deref()
                    .and_then(|p| crate::actionscript::semantic::project_type(self, project, p))
                {
                    Some(parent) => {
                        chain.push(parent.clone());
                        current = parent;
                        continue;
                    }
                    None => break,
                }
            }
            if let Some(info) = self.api.classes.get(&current) {
                chain.extend(info.parents.iter().cloned());
            }
            break;
        }
        let mut unique = HashSet::new();
        chain.retain(|c| unique.insert(c.clone()));
        chain
    }

    /// Members reachable on an instance (`statics == false`) or on the class object itself.
    pub fn members(&self, class: &str, statics: bool) -> Vec<Member> {
        let mut seen = HashSet::new();
        let mut out = Vec::new();
        for owner in self.lineage(class) {
            let project = self.project_class(&owner).map(|c| c.members.iter());
            let builtin = self
                .api
                .by_owner
                .get(&owner)
                .into_iter()
                .flatten()
                .map(|&i| &self.api.members[i]);
            for member in project.into_iter().flatten().chain(builtin) {
                let wanted = match member.kind.as_str() {
                    "constructor" => false,
                    // AS3 events are strings for addEventListener, not members.
                    "event" => !is_as3(self.language) && !statics,
                    "constant" => statics || !is_as3(self.language),
                    _ => member.is_static == statics,
                };
                if wanted && seen.insert(member.name.clone()) {
                    out.push(member.clone());
                }
            }
            if statics {
                break; // static members are not inherited through the class object
            }
        }
        out
    }

    /// Classic Flash CS4 comment hint: `// ClassName varName;` or `/* ClassName varName; */`.
    fn comment_hint_type(&self, source: &str, name: &str, limit: usize) -> Option<String> {
        let head: String = source.chars().take(limit).collect();
        let mut found = None;
        for (range, token) in regions(&head) {
            if token != RegionKind::Comment {
                continue;
            }
            let raw = &head[range];
            let body = if let Some(rest) = raw.strip_prefix("//") {
                rest
            } else if let Some(rest) = raw.strip_prefix("/*") {
                rest.strip_suffix("*/").unwrap_or(rest)
            } else {
                continue;
            };
            for clause in body.split(['\n', ';']) {
                let clause = clause.trim().trim_start_matches('*').trim();
                let ty = ident(clause);
                if ty.is_empty()
                    || !ty
                        .chars()
                        .next()
                        .is_some_and(|c| c.is_alphabetic() || c == '_' || c == '$')
                {
                    continue;
                }
                let rest = &clause[ty.len()..];
                if !rest.starts_with(char::is_whitespace) {
                    continue;
                }
                let rest = rest.trim_start();
                let var_end = rest
                    .char_indices()
                    .find(|(_, c)| !(c.is_alphanumeric() || *c == '_' || *c == '$'))
                    .map_or(rest.len(), |(i, _)| i);
                let var_name = &rest[..var_end];
                let after = rest[var_end..].trim();
                if var_name == name
                    && after.is_empty()
                    && let Some(resolved) = self.resolve_class(ty)
                {
                    found = Some(resolved);
                }
            }
        }
        found
    }

    /// Classic Flash CS4 AS1/AS2 suffix inference (`hero_mc` -> `MovieClip`, `msg_txt` -> `TextField`, ...).
    fn suffix_type(language: ScriptLanguage, name: &str) -> Option<&'static str> {
        if !matches!(
            language,
            ScriptLanguage::ActionScript1 | ScriptLanguage::ActionScript2
        ) {
            return None;
        }
        CLASSIC_VARIABLE_SUFFIXES
            .iter()
            .find_map(|&(suffix, class_name)| {
                (name.len() > suffix.len() && name.ends_with(suffix)).then_some(class_name)
            })
    }

    /// Build a read-only declaration snapshot using the compiler lexer.
    pub fn analyze(&self, source: &str) -> Arc<Analysis> {
        cached_analysis(self.language, source)
    }

    /// Read-only AST type flow. It never changes compilation success or generated code.
    pub fn semantic_analysis(&self, source: &str) -> Arc<SemanticAnalysis> {
        // Source facts depend on the project signatures, current class and stage instances.
        // Exact keys avoid stale completions when another file changes without an editor edit.
        let key = format!(
            "{:?}|{:?}|{:?}|{:?}",
            self.language, self.this_class, self.project, self.instances
        );
        SEMANTICS.with(|cache| {
            let mut cache = cache.borrow_mut();
            if let Some(index) = cache
                .iter()
                .position(|(old, analysis)| old == &key && analysis.source() == source)
            {
                let entry = cache.remove(index).expect("located semantic snapshot");
                let result = Arc::clone(&entry.1);
                cache.push_front(entry);
                return result;
            }
            let analysis = Arc::new(crate::actionscript::semantic::analyze(self, source));
            if source.len() <= 1_048_576 && key.len() + source.len() <= 2_097_152 {
                cache.push_front((key, Arc::clone(&analysis)));
                while cache.len() > 4
                    || cache
                        .iter()
                        .map(|(key, a)| key.len() + a.source().len())
                        .sum::<usize>()
                        > 2_097_152
                {
                    cache.pop_back();
                }
            }
            analysis
        })
    }

    pub(crate) fn flow_lineage(&self, class: &str) -> Vec<String> {
        self.lineage(class)
    }

    fn value_type(&self, ty: &str, indexed: bool) -> Option<String> {
        let ty = if indexed {
            ty.strip_prefix("Vector.<")?.strip_suffix('>')?
        } else {
            ty
        };
        self.resolve_class(ty)
    }

    /// Resolve a member/call chain. Unknown/dynamic values deliberately have no guessed type.
    #[cfg(test)]
    fn receiver_type(&self, chain: &[&str], source: &str, caret: usize) -> Option<String> {
        self.receiver_type_in(
            chain,
            &self.analyze(source),
            &self.semantic_analysis(source),
            caret,
        )
    }

    fn receiver_type_in(
        &self,
        chain: &[&str],
        analysis: &Analysis,
        semantic: &SemanticAnalysis,
        caret: usize,
    ) -> Option<String> {
        let source = analysis.source();
        let (first, rest) = chain.split_first()?;
        if chain.len() > 1
            && let Some(class) = self.resolve_class(&chain.join("."))
        {
            return Some(format!("static:{class}"));
        }
        let segment = |part: &str| {
            let end = part.find(['(', '[']).unwrap_or(part.len());
            (
                part[..end].to_owned(),
                part[end..].starts_with('('),
                part.ends_with(']'),
            )
        };
        let (name, call, indexed) = segment(first);
        // The receiver/callee is evaluated before its arguments and any callback effects.
        // Query its entry state; the state after create(args) may correctly invalidate create.
        let receiver_start = caret.saturating_sub(
            chain.iter().map(|part| part.chars().count()).sum::<usize>() + chain.len(),
        );
        let mut current = match name.as_str() {
            "this" => self.this_class.clone(),
            "super" => self.lineage(&self.this_class).get(1)?.clone(),
            name => {
                if semantic.has_binding(name, receiver_start) {
                    let ty = if call {
                        semantic.return_type(name, receiver_start)
                    } else {
                        semantic.type_at(name, receiver_start)
                    }?;
                    self.value_type(&ty, indexed)?
                } else if let Some(local) = analysis.resolve(name, caret) {
                    if semantic.is_analyzed(caret) {
                        return None;
                    }

                    // A local shadows a stage/class name even when its type is unknown.
                    if call && local.kind != SymbolKind::Function {
                        return None;
                    }
                    self.value_type(&local.ty, indexed)?
                } else if call {
                    self.resolve_class(name).or_else(|| {
                        let member = self
                            .members(&self.this_class, false)
                            .into_iter()
                            .find(|m| m.name == name && m.callable())?;
                        crate::actionscript::semantic::member_type(self, &member, &member.ty)
                            .and_then(|ty| self.value_type(&ty, indexed))
                    })?
                } else {
                    self.comment_hint_type(source, name, caret)
                        .or_else(|| {
                            self.instances
                                .iter()
                                .find(|(n, _)| n == name)
                                .map(|(_, class)| class.clone())
                        })
                        .or_else(|| {
                            self.resolve_class(name)
                                .map(|class| format!("static:{class}"))
                        })
                        .or_else(|| {
                            Self::suffix_type(self.language, name)
                                .and_then(|ty| self.resolve_class(ty))
                        })
                        .or_else(|| {
                            let member = self
                                .members(&self.this_class, false)
                                .into_iter()
                                .find(|m| m.name == name)?;
                            crate::actionscript::semantic::member_type(self, &member, &member.ty)
                                .and_then(|ty| self.value_type(&ty, indexed))
                        })?
                }
            }
        };
        for part in rest {
            let (name, call, indexed) = segment(part);
            let (class, statics) = current
                .strip_prefix("static:")
                .map_or((current.as_str(), false), |class| (class, true));
            let member = self
                .members(class, statics)
                .into_iter()
                .find(|m| m.name == name && (!call || m.callable()));
            current = if let Some(member) = member {
                crate::actionscript::semantic::member_type(self, &member, &member.ty)
                    .and_then(|ty| self.value_type(&ty, indexed))?
            } else {
                if call || class != self.this_class {
                    return None;
                }
                self.instances.iter().find(|(n, _)| n == &name)?.1.clone()
            };
        }
        Some(current)
    }

    /// Code hints for `source` with the caret at char index `caret`.
    /// `explicit` (⌃Space / toolbar) also lists scope names without a typed prefix.
    pub fn hints(&self, source: &str, caret: usize, explicit: bool) -> Option<Hints> {
        self.analyze(source).completions(self, caret, explicit)
    }

    fn hints_in(&self, analysis: &Analysis, caret: usize, explicit: bool) -> Option<Hints> {
        let source = analysis.source();
        let chars: Vec<char> = source.chars().collect();
        let caret = caret.min(chars.len());
        let is_ident = |c: char| c.is_alphanumeric() || c == '_' || c == '$';
        let mut start = caret;
        while start > 0 && is_ident(chars[start - 1]) {
            start -= 1;
        }
        if in_comment_or_string(source, start) {
            return None;
        }
        let prefix: String = chars[start..caret].iter().collect();
        let mut candidates: Vec<Member> = Vec::new();
        if start > 0 && chars[start - 1] == '.' {
            let mut chain = Vec::new();
            let mut end = start - 1;
            loop {
                let mut s = end;
                let mut depth = 0usize;
                while s > 0 {
                    let ch = chars[s - 1];
                    if matches!(ch, ')' | ']') {
                        depth += 1;
                    } else if matches!(ch, '(' | '[') {
                        if depth == 0 {
                            break;
                        }
                        depth -= 1;
                    } else if depth == 0 && !is_ident(ch) {
                        break;
                    }
                    s -= 1;
                }
                if s == end || depth != 0 {
                    return None;
                }
                chain.push(chars[s..end].iter().collect::<String>());
                if s > 0 && chars[s - 1] == '.' {
                    end = s - 1;
                } else {
                    break;
                }
            }
            chain.reverse();
            let chain: Vec<&str> = chain.iter().map(String::as_str).collect();
            let semantic = self.semantic_analysis(source);
            let receiver = self.receiver_type_in(&chain, analysis, &semantic, start)?;
            candidates = match receiver.strip_prefix("static:") {
                Some(class) => self.members(class, true),
                None => self.members(&receiver, false),
            };
        } else {
            if prefix.is_empty() && !explicit {
                return None;
            }
            if start > 0 && chars[..start].iter().rev().find(|c| !c.is_whitespace()) == Some(&':') {
                // Type annotation: classes only.
                candidates.extend(self.class_members());
            } else {
                let semantic = self.semantic_analysis(source);
                candidates.extend(analysis.visible_symbols(caret).into_iter().map(|symbol| {
                    Member {
                        owner: String::new(),
                        name: symbol.name.clone(),
                        kind: "local".into(),
                        ty: if semantic.has_binding(&symbol.name, caret) {
                            semantic.type_at(&symbol.name, caret).unwrap_or_default()
                        } else {
                            symbol.ty.clone()
                        },
                        is_static: false,
                        params: symbol.params.clone(),
                        group: None,
                        limitation: None,
                    }
                }));
                candidates.extend(self.members(&self.this_class, false));
                candidates.extend(self.globals());
                candidates.extend(self.class_members());
                candidates.extend(self.instances.iter().map(|(name, class)| Member {
                    owner: String::new(),
                    name: name.clone(),
                    kind: "property".into(),
                    ty: short_name(class).to_owned(),
                    is_static: false,
                    params: None,
                    group: None,
                    limitation: None,
                }));
            }
        }
        let lower = prefix.to_lowercase();
        let mut seen = HashSet::new();
        let mut items: Vec<Hint> = candidates
            .into_iter()
            .filter(|m| m.name.to_lowercase().starts_with(&lower) && m.name != prefix)
            .filter(|m| seen.insert(m.name.clone()))
            .map(|m| {
                let (insert, caret) = m.insertion();
                Hint {
                    label: m.label(),
                    detail: short_name(&m.ty).to_owned(),
                    insert,
                    caret,
                }
            })
            .collect();
        items.sort_by(|a, b| {
            let exact = |h: &Hint| !h.label.starts_with(&prefix);
            exact(a)
                .cmp(&exact(b))
                .then_with(|| a.label.to_lowercase().cmp(&b.label.to_lowercase()))
        });
        items.truncate(200);
        (!items.is_empty()).then_some(Hints { start, items })
    }

    fn globals(&self) -> Vec<Member> {
        self.api
            .by_owner
            .get("")
            .into_iter()
            .flatten()
            .map(|&i| &self.api.members[i])
            .filter(|m| m.group.is_none())
            .cloned()
            .collect()
    }

    /// Class names as completion candidates (short names; type column says "class").
    fn class_members(&self) -> Vec<Member> {
        self.project
            .iter()
            .map(|c| c.qualified.clone())
            .chain(self.api.classes.keys().cloned())
            .filter(|q| !q.is_empty())
            .map(|qualified| Member {
                owner: String::new(),
                name: short_name(&qualified).to_owned(),
                kind: "class".into(),
                ty: "class".into(),
                is_static: false,
                params: None,
                group: None,
                limitation: None,
            })
            .collect()
    }
}

impl Analysis {
    /// Complete against the shared built-in/project/instance context without rebuilding this snapshot.
    pub fn completions(
        &self,
        context: &HintContext<'_>,
        offset_chars: usize,
        explicit: bool,
    ) -> Option<Hints> {
        context.hints_in(self, offset_chars, explicit)
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct PartialApiUse {
    pub line: usize,
    pub column: usize,
    pub span: (usize, usize),
    pub owner: String,
    pub member: String,
    pub limitation: String,
}

/// Audited limitations on conservatively resolved direct built-in member uses. Dynamic names,
/// project fields, wildcard/ambiguous imports and untyped receivers do not generate guesses.
pub fn partial_api_uses(script: &Script) -> Vec<PartialApiUse> {
    let Some(api) = api(script.language) else {
        return Vec::new();
    };
    let analysis = cached_analysis(script.language, &script.source);
    let imports = analysis.imports();
    let resolve = |ty: &str| -> Option<String> {
        if analysis
            .classes()
            .iter()
            .any(|c| c.qualified == ty || short_name(&c.qualified) == ty)
        {
            return None;
        }
        if ty.contains('.') {
            return api.classes.contains_key(ty).then(|| ty.to_owned());
        }
        let matches: Vec<_> = imports
            .iter()
            .filter(|q| short_name(q) == ty && api.classes.contains_key(q.as_str()))
            .collect();
        match matches.as_slice() {
            [qualified] => Some((*qualified).clone()),
            _ => None,
        }
    };
    let context = HintContext {
        language: script.language,
        api,
        project: Vec::new(),
        this_class: String::new(),
        instances: Vec::new(),
    };
    analysis
        .direct_member_uses()
        .into_iter()
        .filter_map(|(receiver, name, span)| {
            let caret = script.source[..span.start].chars().count();
            let (class, statics) = if let Some(local) = analysis.resolve(receiver, caret) {
                (resolve(&local.ty)?, false)
            } else {
                (resolve(receiver)?, true)
            };
            let member = context
                .members(&class, statics)
                .into_iter()
                .find(|m| m.name == name)?;
            let limitation = member.limitation?;
            let (line, column) = crate::byte_offset_to_line_col(&script.source, span.start);
            Some(PartialApiUse {
                line,
                column,
                span: (span.start, span.end),
                owner: member.owner,
                member: name.into(),
                limitation,
            })
        })
        .collect()
}

/// What `this` / a named instance is, from the document model.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum ThisKind {
    MovieClip,
    Button,
    Text,
    Bitmap,
    Shape,
}

impl ThisKind {
    pub fn of_element(project: &Project, kind: &ElementKind) -> Self {
        match kind {
            ElementKind::Instance { symbol_id, .. } => {
                match project.symbol(symbol_id).map(|s| s.kind) {
                    Some(neoflash_core::SymbolKind::Button) => Self::Button,
                    _ => Self::MovieClip,
                }
            }
            ElementKind::Text { .. } | ElementKind::TextBox { .. } => Self::Text,
            ElementKind::Bitmap { .. } => Self::Bitmap,
            _ => Self::Shape,
        }
    }
}

/// True when char index `at` lies inside a comment or string literal (also an unterminated one
/// that ends at `at`, as while typing).
pub fn in_comment_or_string(source: &str, at: usize) -> bool {
    let byte = source
        .char_indices()
        .nth(at)
        .map_or(source.len(), |(i, _)| i);
    regions(source).into_iter().any(|(range, token)| {
        let text = &source[range.clone()];
        let closed = match token {
            RegionKind::Comment => {
                text.starts_with("/*") && text.len() >= 4 && text.ends_with("*/")
            }
            RegionKind::String => {
                text.len() >= 2 && text.ends_with(&text[..1]) && !text.ends_with("\\\"")
            }
        };
        range.start < byte && (byte < range.end || (byte == range.end && !closed))
    })
}

// ---------------------------------------------------------------------------------------------
// Toolbox

/// One toolbox folder: a package, "Top level", "Language elements" or "Project classes".
pub struct ToolboxFolder {
    pub label: String,
    /// Qualified class names in this folder.
    pub classes: Vec<String>,
    /// Folder-level entries (global functions, language elements).
    pub entries: Vec<Member>,
}

pub const TOP_LEVEL: &str = "Top level";
pub const LANGUAGE_ELEMENTS: &str = "Language elements";
pub const PROJECT_CLASSES: &str = "Project classes";

/// Toolbox tree of the language: Top level, Language elements, Project classes, then packages A–Z.
pub fn toolbox(project: &[ProjectClass], api: &LanguageApi) -> Vec<ToolboxFolder> {
    let mut top = ToolboxFolder {
        label: TOP_LEVEL.into(),
        classes: Vec::new(),
        entries: Vec::new(),
    };
    let mut language = ToolboxFolder {
        label: LANGUAGE_ELEMENTS.into(),
        classes: Vec::new(),
        entries: Vec::new(),
    };
    let mut packages: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for qualified in api.classes.keys() {
        match package_of(qualified) {
            "" => top.classes.push(qualified.clone()),
            package => packages
                .entry(package.to_owned())
                .or_default()
                .push(qualified.clone()),
        }
    }
    for &i in api.by_owner.get("").into_iter().flatten() {
        let member = &api.members[i];
        if member.group.is_some() {
            language.entries.push(member.clone());
        } else {
            top.entries.push(member.clone());
        }
    }
    let mut folders = vec![top, language];
    if !project.is_empty() {
        folders.push(ToolboxFolder {
            label: PROJECT_CLASSES.into(),
            classes: project.iter().map(|c| c.qualified.clone()).collect(),
            entries: Vec::new(),
        });
    }
    folders.extend(packages.into_iter().map(|(label, classes)| ToolboxFolder {
        label,
        classes,
        entries: Vec::new(),
    }));
    folders
}

/// Members listed under a class in the toolbox: its own declarations (static and instance).
pub fn own_members(project: &[ProjectClass], api: &LanguageApi, class: &str) -> Vec<Member> {
    if let Some(project) = project.iter().find(|c| c.qualified == class) {
        return project.members.clone();
    }
    api.by_owner
        .get(class)
        .into_iter()
        .flatten()
        .map(|&i| api.members[i].clone())
        .collect()
}

/// Toolbox search: classes and members whose name contains `needle` (case-insensitive).
pub fn search(
    project: &[ProjectClass],
    api: &LanguageApi,
    needle: &str,
    limit: usize,
) -> Vec<Member> {
    let needle = needle.to_lowercase();
    let classes = project
        .iter()
        .map(|c| c.qualified.clone())
        .chain(api.classes.keys().cloned())
        .filter(|q| short_name(q).to_lowercase().contains(&needle))
        .map(|qualified| Member {
            owner: qualified.clone(),
            name: short_name(&qualified).to_owned(),
            kind: "class".into(),
            ty: String::new(),
            is_static: false,
            params: None,
            group: None,
            limitation: None,
        });
    let members = project
        .iter()
        .flat_map(|c| c.members.iter())
        .chain(api.members.iter())
        .filter(|m| m.name.to_lowercase().contains(&needle))
        .cloned();
    classes.chain(members).take(limit).collect()
}

/// `import a.b.C;` needed in AS3 to use `qualified` from a frame script, if not already imported.
pub fn missing_import(source: &str, qualified: &str) -> Option<String> {
    let package = package_of(qualified);
    if package.is_empty() {
        return None;
    }
    let exact = format!("import {qualified};");
    let wildcard = format!("import {package}.*;");
    let compact: String = source.split_whitespace().collect::<Vec<_>>().join(" ");
    (!compact.contains(&exact) && !compact.contains(&wildcard)).then_some(exact)
}

#[cfg(test)]
mod tests {
    use super::*;

    fn context(language: ScriptLanguage) -> HintContext<'static> {
        HintContext::new(&Project::demo(), language, ThisKind::MovieClip).unwrap()
    }

    #[test]
    fn index_only_contains_ready_statuses() {
        for language in [ScriptLanguage::ActionScript2, ScriptLanguage::ActionScript3] {
            let api = api(language).unwrap();
            assert!(api.members.len() > 500);
            assert!(
                api.classes
                    .values()
                    .all(|c| matches!(c.status.as_str(), "subset" | "partial" | "members"))
            );
        }
        assert!(api(ScriptLanguage::JavaScript).is_none());
    }

    #[test]
    fn this_members_include_inherited_display_api() {
        let hints = context(ScriptLanguage::ActionScript3)
            .hints("this.", 5, false)
            .unwrap();
        let labels: Vec<_> = hints.items.iter().map(|h| h.label.as_str()).collect();
        assert!(labels.contains(&"gotoAndPlay()"), "{labels:?}");
        assert!(labels.contains(&"x"), "MovieClip inherits DisplayObject.x");
        assert_eq!(hints.start, 5);
    }

    #[test]
    fn declared_variables_and_static_members_resolve() {
        let as3 = context(ScriptLanguage::ActionScript3);
        let source = "var p:Point = new Point();\np.";
        let hints = as3.hints(source, source.chars().count(), false).unwrap();
        assert!(hints.items.iter().any(|h| h.label == "x"));
        let source = "addEventListener(MouseEvent.CL";
        let hints = as3.hints(source, source.chars().count(), false).unwrap();
        assert_eq!(hints.items[0].label, "CLICK");
        assert_eq!(hints.start, source.chars().count() - 2);
    }

    #[test]
    fn as2_uses_its_own_api_and_no_hints_in_comments() {
        let as2 = context(ScriptLanguage::ActionScript2);
        let hints = as2.hints("this._", 6, false).unwrap();
        assert!(hints.items.iter().any(|h| h.label == "_alpha"));
        assert!(as2.hints("// this.", 8, false).is_none());
        assert!(as2.hints("trace(\"this.", 12, false).is_none());
    }

    #[test]
    fn project_classes_are_offered_without_rebuilding_the_index() {
        let mut project = Project::demo();
        project.sources.push(SourceUnit {
            id: "s".into(),
            path: "game/Hero.as".into(),
            language: ScriptLanguage::ActionScript3,
            source: "package game {\n  public class Hero extends flash.display.Sprite {\n    public var lives:int = 3;\n    public function jump(height:Number):void {}\n    private function secret():void {}\n    public static function create():Hero { return new Hero(); }\n  }\n}\n".into(),
        });
        let context =
            HintContext::new(&project, ScriptLanguage::ActionScript3, ThisKind::MovieClip).unwrap();
        let source = "var h:Hero = Hero.create();\nh.";
        let labels: Vec<_> = context
            .hints(source, source.chars().count(), false)
            .unwrap()
            .items
            .into_iter()
            .map(|h| h.label)
            .collect();
        assert!(labels.contains(&"jump()".to_owned()));
        assert!(labels.contains(&"lives".to_owned()));
        assert!(
            labels.contains(&"x".to_owned()),
            "inherits Sprite/DisplayObject"
        );
        assert!(!labels.contains(&"secret()".to_owned()));
        let statics = context.hints("Hero.", 5, false).unwrap();
        assert_eq!(statics.items[0].label, "create()");
        let folders = toolbox(&context.project, context.api);
        assert!(folders.iter().any(|f| f.label == PROJECT_CLASSES));
    }

    #[test]
    fn imports_are_only_requested_once() {
        assert_eq!(
            missing_import("", "flash.geom.Point").as_deref(),
            Some("import flash.geom.Point;")
        );
        assert!(missing_import("import flash.geom.*;", "flash.geom.Point").is_none());
        assert!(missing_import("", "Math").is_none());
    }

    #[test]
    fn all_25_classic_as2_variable_suffixes_resolve_code_hints() {
        assert_eq!(CLASSIC_VARIABLE_SUFFIXES.len(), 25);
        for lang in [ScriptLanguage::ActionScript1, ScriptLanguage::ActionScript2] {
            let ctx = HintContext::new(&Project::demo(), lang, ThisKind::MovieClip).unwrap();
            for (suffix, expected_class) in CLASSIC_VARIABLE_SUFFIXES {
                let var_name = format!("item{suffix}");
                let resolved = ctx.receiver_type(&[var_name.as_str()], "", 0);
                assert_eq!(
                    resolved.as_deref(),
                    Some(expected_class),
                    "suffix {suffix} should resolve to {expected_class}"
                );
                let src = format!("{var_name}.");
                let hints = ctx
                    .hints(&src, src.chars().count(), false)
                    .unwrap_or_else(|| panic!("expected hints for {src}"));
                assert!(
                    !hints.items.is_empty(),
                    "expected non-empty members for {expected_class}"
                );
            }
            // Bare `_mc` without a prefix must not be treated as a suffixed variable.
            assert!(ctx.hints("_mc.", 4, false).is_none());
        }
    }

    #[test]
    fn comment_type_hints_resolve_in_as2_and_as3() {
        let as2 = context(ScriptLanguage::ActionScript2);
        let src_as2 = "// MovieClip myVar;\n/* TextField labelBox; */\nmyVar.";
        let hints = as2
            .hints(src_as2, src_as2.chars().count(), false)
            .expect("AS2 comment hint");
        assert!(hints.items.iter().any(|h| h.label == "gotoAndPlay()"));

        let src_box = "// MovieClip myVar;\n/* TextField labelBox; */\nlabelBox.";
        let box_hints = as2
            .hints(src_box, src_box.chars().count(), false)
            .expect("AS2 block comment hint");
        assert!(box_hints.items.iter().any(|h| h.label == "htmlText"));

        let as3 = context(ScriptLanguage::ActionScript3);
        let src_as3 = "// flash.display.MovieClip heroClip;\nheroClip.";
        let as3_hints = as3
            .hints(src_as3, src_as3.chars().count(), false)
            .expect("AS3 comment hint");
        assert!(as3_hints.items.iter().any(|h| h.label == "gotoAndStop()"));
    }
    #[test]
    fn scoped_analysis_and_multiline_project_members_feed_real_hints() {
        let as3 = context(ScriptLanguage::ActionScript3);
        let source = "var point = new Point();\nfunction inner(\n point:TextField\n):void { point. }\npoint.";
        let inside = source.find("point. }").unwrap() + 6;
        let inner = as3.hints(source, inside, false).unwrap();
        assert!(inner.items.iter().any(|h| h.label == "htmlText"));
        let outside = as3.hints(source, source.chars().count(), false).unwrap();
        assert!(outside.items.iter().any(|h| h.label == "length"));
        assert!(!outside.items.iter().any(|h| h.label == "htmlText"));
        let fake = "var point:Point; function f(){ var point; point.";
        assert!(
            as3.hints(fake, fake.chars().count(), false).is_none(),
            "unknown local shadows outer typed local"
        );
        let source =
            "function create(\n value:Number\n):Point { return new Point(value,0); }\ncreate(3).";
        assert!(
            as3.hints(source, source.chars().count(), false)
                .unwrap()
                .items
                .iter()
                .any(|h| h.label == "length")
        );
        let source = "var points:Vector.<Point>; points[0].";
        assert!(
            as3.hints(source, source.chars().count(), false)
                .unwrap()
                .items
                .iter()
                .any(|h| h.label == "length")
        );
        let source = "var text:String; function hidden(secret:Point) { var local:Point; }\nse";
        let hints = as3.hints(source, source.chars().count(), true);
        assert!(hints.is_none_or(|h| {
            h.items
                .iter()
                .all(|h| h.label != "secret" && h.label != "local")
        }));

        let unit = SourceUnit {id:"multi".into(),path:"demo/Hero.as".into(),language:ScriptLanguage::ActionScript3,
            source:"package demo { public class Hero extends flash.display.Sprite { public function jump(\n height:Number,\n origin:Point\n):Point { var internalOnly:Number; return origin; } public\n var score:Number; private function hidden():void {} } }".into()};
        let class = scan_class(&unit).unwrap();
        assert_eq!(class.qualified, "demo.Hero");
        assert_eq!(class.parent.as_deref(), Some("flash.display.Sprite"));
        assert_eq!(class.members.len(), 2);
        let jump = class.members.iter().find(|m| m.name == "jump").unwrap();
        assert_eq!(jump.ty, "Point");
        assert!(jump.params.as_ref().unwrap().contains("origin:Point"));
        assert!(
            class
                .members
                .iter()
                .any(|m| m.name == "score" && m.ty == "Number")
        );

        let source = "// β\nvar point:Point;\npoint.x;";
        let analysis = as3.analyze(source);
        let at = source[..source.rfind("point").unwrap()].chars().count();
        let range = analysis.definition(at).unwrap();
        assert_eq!(&source[range], "point");
        assert_eq!(analysis.hover(at).as_deref(), Some("point: Point"));
    }
    #[test]
    fn partial_api_limits_use_audited_receiver_and_never_same_named_members() {
        let script = |source: &str| Script {
            language: ScriptLanguage::ActionScript3,
            source: source.into(),
        };
        let source = "import flash.net.Socket; var connection:Socket = new Socket(); connection.connect('localhost',80);";
        let diagnostics = partial_api_uses(&script(source));
        assert_eq!(diagnostics.len(), 1);
        assert_eq!(diagnostics[0].owner, "flash.net.Socket");
        assert_eq!(
            &source[diagnostics[0].span.0..diagnostics[0].span.1],
            "connect"
        );
        assert!(diagnostics[0].limitation.contains("TCP"));
        for source in [
            "var connection:Object; connection.connect();",
            "import flash.net.Socket; function f(connection:Object):void { connection.connect(); }",
            "import flash.net.Socket; class Socket { public function connect():void {} } var connection:Socket; connection.connect();",
            "import flash.net.Socket; var connection:Socket; trace('connection.connect()');",
            "import flash.net.Socket; var connection:Socket; var pattern:RegExp=/connection.connect/;",
        ] {
            assert!(partial_api_uses(&script(source)).is_empty(), "{source}");
        }
        let context = context(ScriptLanguage::ActionScript3);
        let first = context.analyze("var value:Point; value.");
        assert!(Arc::ptr_eq(
            &first,
            &context.analyze("var value:Point; value.")
        ));
        assert!(!Arc::ptr_eq(
            &first,
            &context.analyze("var value:TextField; value.")
        ));
    }
}
